public synchronized List<Entry> entries() { return List.copyOf(entries); }

private void load() {
    if (!Files.isRegularFile(path)) return;
    try {
        if (Files.size(path) > MAXIMUM_FILE_BYTES) {
            persist();
            return;
        }
        for (String line : Files.readAllLines(path, StandardCharsets.UTF_8)) {
            if (line.isBlank() || line.getBytes(StandardCharsets.UTF_8).length > MAXIMUM_LINE_BYTES) {
                entries.clear();
                persist();
                return;
            }
            JsonNode root = MAPPER.readTree(line);
            var fields = new java.util.TreeMap<String, String>();
            JsonNode rawFields = root.path("fields");
            if (!rawFields.isObject()) throw new IOException("invalid retained log fields");
            rawFields.properties().forEach(field -> {
                if (ALLOWED_FIELDS.contains(field.getKey()) && field.getValue().isTextual()) {
                    String value = field.getValue().textValue();
                    if (!value.isBlank() && value.length() <= 256
                            && value.chars().noneMatch(Character::isISOControl)) fields.put(field.getKey(), value);
                }
            });
            entries.add(new Entry(root.required("id").textValue(),
                    Instant.parse(root.required("occurredAt").textValue()),
                    root.required("type").textValue(), fields));
            if (entries.size() > maximumEntries) entries.removeFirst();
        }
    } catch (IOException | RuntimeException corruptProjection) {
        entries.clear();
        persist();
    }
}

